INSERT INTO answers (question_id, admin_id, content, created_at, updated_at)
SELECT q.id, adm.id, a.content, a.ans_date, NULL
FROM (VALUES
  ('jihoon@company.com','커밋 메시지는 어떤 형식으로 작성하나요?',TIMESTAMP '2024-09-27 10:13:01','jeonghyeon@company.com',TIMESTAMP '2024-09-28 09:00:00','커밋은 type(scope): 요약 형식을 사용합니다. 예: feat(qna): 질문 등록 API 추가. 본문에는 변경한 이유를 함께 적습니다.'),
  ('jihoon@company.com','연차는 입사 후 언제부터 사용할 수 있나요?',TIMESTAMP '2025-02-05 11:26:02','jeonghyeon@company.com',TIMESTAMP '2025-02-06 09:00:00','연차는 입사일 기준으로 발생하며, 전자결재의 휴가 신청 메뉴에서 신청 후 팀장 승인을 받으면 사용할 수 있습니다. 입사 1년 미만은 매월 1일씩 발생합니다.'),
  ('jihoon@company.com','코드 리뷰는 어떤 절차로 진행되나요?',TIMESTAMP '2025-06-15 12:39:03','jeonghyeon@company.com',TIMESTAMP '2025-06-16 09:00:00','PR을 올리면 최소 1인 이상의 승인과 CI 통과가 필요하며, 리뷰 의견을 반영한 뒤 develop 브랜치로 머지합니다.'),
  ('jihoon@company.com','PR은 어떤 조건을 충족해야 머지할 수 있나요?',TIMESTAMP '2025-10-24 13:52:04','jeonghyeon@company.com',TIMESTAMP '2025-10-25 09:00:00','PR은 리뷰어 1인 이상 승인과 CI 빌드·테스트 통과가 필수이며, 충돌이 있으면 해결한 뒤 머지합니다.'),
  ('jihoon@company.com','로컬 개발 환경은 어떻게 세팅하나요?',TIMESTAMP '2026-03-03 14:05:05','jeonghyeon@company.com',TIMESTAMP '2026-03-04 09:00:00','JDK/Node 등 필수 런타임을 설치한 뒤 저장소 README의 로컬 실행 절차를 따르면 되며, 상세 내용은 ''개발 환경 세팅 가이드'' 문서를 참고하세요.'),
  ('yujun@company.com','로컬 빌드가 너무 느린데 개선 방법이 있나요?',TIMESTAMP '2024-11-13 15:18:06','jeonghyeon@company.com',TIMESTAMP '2024-11-14 09:00:00','빌드 캐시(Gradle/npm)를 활용하고 불필요한 클린 빌드를 줄이면 개선됩니다. 장비 성능 문제라면 인프라팀에 사양 점검을 요청하세요.'),
  ('yujun@company.com','단위 테스트는 어떻게 실행하나요?',TIMESTAMP '2025-06-03 09:44:08','jeonghyeon@company.com',TIMESTAMP '2025-06-04 09:00:00','백엔드는 ./gradlew test, 프론트는 npm run test로 실행하며, PR 전 로컬에서 통과를 확인한 뒤 올리는 것을 권장합니다.'),
  ('yujun@company.com','CI가 실패하면 어떻게 대응하나요?',TIMESTAMP '2025-09-12 10:57:09','jeonghyeon@company.com',TIMESTAMP '2025-09-13 09:00:00','실패 로그를 확인해 원인을 파악하고 로컬에서 재현·수정한 뒤 다시 푸시합니다. 반복 실패 시 데브옵스 채널에 문의하세요.'),
  ('yujun@company.com','린트 규칙은 어디에 정의되어 있나요?',TIMESTAMP '2025-12-22 11:10:10','jeonghyeon@company.com',TIMESTAMP '2025-12-23 09:00:00','린트 규칙은 저장소의 ESLint 설정에 정의되어 있으며, 커밋 전 npm run lint로 확인하고 자동 수정은 lint:fix를 사용합니다.'),
  ('yuna@company.com','반차 사용 시 전자결재 서류는 언제까지 올려야 하나요?',TIMESTAMP '2025-01-04 13:36:12','jeonghyeon@company.com',TIMESTAMP '2025-01-05 09:00:00','반차 신청은 사용일 전날까지 전자결재로 상신해야 하며, 승인 완료 후 근태 시스템에 자동 반영됩니다.'),
  ('yuna@company.com','DB 마이그레이션은 어떻게 관리하나요?',TIMESTAMP '2025-04-06 14:49:13','jeonghyeon@company.com',TIMESTAMP '2025-04-07 09:00:00','스키마 변경은 마이그레이션 스크립트로 관리하며 리뷰를 거쳐 적용합니다. 로컬은 ddl-auto로 반영되지만 운영은 스크립트로 배포합니다.'),
  ('yuna@company.com','API 문서는 어디서 확인하나요?',TIMESTAMP '2025-10-08 16:15:15','jeonghyeon@company.com',TIMESTAMP '2025-10-09 09:00:00','API 문서는 Swagger(/swagger-ui) 또는 API 명세서에서 확인할 수 있으며, API를 변경하면 명세도 함께 갱신합니다.'),
  ('yuna@company.com','경조사 지원은 어떻게 신청하나요?',TIMESTAMP '2026-04-10 10:41:17','jeonghyeon@company.com',TIMESTAMP '2026-04-11 09:00:00','경조사 지원은 총무팀에 경조사 신청서와 증빙 서류를 제출하면 되며, 경조 휴가와 경조금이 함께 처리됩니다.'),
  ('yewon@company.com','예외 처리는 어떤 기준으로 하나요?',TIMESTAMP '2024-12-08 11:54:18','jeonghyeon@company.com',TIMESTAMP '2024-12-09 09:00:00','비즈니스 예외는 공통 예외 체계를 사용해 일관된 응답 형식으로 반환하며, 예상치 못한 오류는 전역 예외 핸들러에서 처리합니다.'),
  ('yewon@company.com','피처 플래그는 어떻게 사용하나요?',TIMESTAMP '2025-03-15 12:07:19','jeonghyeon@company.com',TIMESTAMP '2025-03-16 09:00:00','피처 플래그는 미완성·실험 기능을 조건부로 노출할 때 사용하며, 배포 후 안정화되면 플래그를 제거합니다.'),
  ('yewon@company.com','캐시는 어떻게 관리하나요?',TIMESTAMP '2025-06-20 13:20:20','jeonghyeon@company.com',TIMESTAMP '2025-06-21 09:00:00','자주 조회되는 데이터는 캐시를 활용하되 갱신 정책을 명확히 하고, 데이터 정합성이 중요한 경우 캐시 무효화 처리를 함께 합니다.'),
  ('yewon@company.com','재택근무는 어떤 절차로 신청하나요?',TIMESTAMP '2025-12-30 15:46:22','jeonghyeon@company.com',TIMESTAMP '2025-12-31 09:00:00','재택근무는 전자결재로 사전 신청 후 팀장 승인을 받아 진행하며, 코어타임(10~16시) 근무와 사내 메신저 상태 유지가 필요합니다.'),
  ('dogyeong@company.com','develop에 머지하기 전 무엇을 확인해야 하나요?',TIMESTAMP '2024-07-04 09:12:24','jeonghyeon@company.com',TIMESTAMP '2024-07-05 09:00:00','최신 develop을 반영해 충돌을 해결하고, CI 통과와 리뷰 승인을 확인한 뒤 머지합니다.'),
  ('dogyeong@company.com','핫픽스는 어떤 브랜치에서 작업하나요?',TIMESTAMP '2024-11-04 10:25:25','jeonghyeon@company.com',TIMESTAMP '2024-11-05 09:00:00','배포 후 긴급 수정은 main에서 hotfix/ 브랜치로 분기해 작업하고, main과 develop 양쪽에 반영합니다.'),
  ('dogyeong@company.com','테스트용 더미 데이터는 어떻게 준비하나요?',TIMESTAMP '2025-03-07 11:38:26','jeonghyeon@company.com',TIMESTAMP '2025-03-08 09:00:00','로컬은 시드 스크립트로 더미데이터를 주입하며, 재기동 시 초기화되는 환경에서는 스크립트로 다시 채웁니다.'),
  ('dogyeong@company.com','교육비는 얼마까지 지원받을 수 있나요?',TIMESTAMP '2025-07-08 12:51:27','jeonghyeon@company.com',TIMESTAMP '2025-07-09 09:00:00','교육비는 연 50만원 한도로 지원되며, 팀장 승인 후 전자결재로 신청하고 수료증과 영수증을 제출하면 정산됩니다.'),
  ('jimin@company.com','로컬 DB를 초기 상태로 되돌리려면 어떻게 하나요?',TIMESTAMP '2024-08-03 15:30:30','jeonghyeon@company.com',TIMESTAMP '2024-08-04 09:00:00','로컬은 create-drop 설정이라 재기동 시 초기화되며, 시드 스크립트로 더미데이터를 다시 넣을 수 있습니다.'),
  ('jimin@company.com','Git 브랜치명은 어떤 규칙으로 작성하나요?',TIMESTAMP '2024-11-29 16:43:31','jeonghyeon@company.com',TIMESTAMP '2024-11-30 09:00:00','브랜치명은 작업 유형, 담당 영역, 이슈 번호, 작업 내용을 포함하는 형식으로 작성합니다. 예시는 feat/be/F-012-login-api 또는 fix/fe/F-021-user-modal-error 와 같습니다.'),
  ('jimin@company.com','출장 신청과 정산은 어떻게 하나요?',TIMESTAMP '2025-03-27 09:56:32','jeonghyeon@company.com',TIMESTAMP '2025-03-28 09:00:00','출장은 전자결재 출장 신청서로 사전 상신하고, 복귀 후 3일 이내 교통비·숙박비 영수증을 첨부해 정산합니다.'),
  ('jimin@company.com','커밋 메시지는 어떤 형식으로 작성하나요?',TIMESTAMP '2025-07-23 10:09:33','jeonghyeon@company.com',TIMESTAMP '2025-07-24 09:00:00','커밋은 type(scope): 요약 형식을 사용합니다. 예: feat(qna): 질문 등록 API 추가. 본문에는 변경한 이유를 함께 적습니다.'),
  ('jimin@company.com','코드 리뷰는 어떤 절차로 진행되나요?',TIMESTAMP '2025-11-18 11:22:34','jeonghyeon@company.com',TIMESTAMP '2025-11-19 09:00:00','PR을 올리면 최소 1인 이상의 승인과 CI 통과가 필요하며, 리뷰 의견을 반영한 뒤 develop 브랜치로 머지합니다.'),
  ('jimin@company.com','PR은 어떤 조건을 충족해야 머지할 수 있나요?',TIMESTAMP '2026-03-16 12:35:35','jeonghyeon@company.com',TIMESTAMP '2026-03-17 09:00:00','PR은 리뷰어 1인 이상 승인과 CI 빌드·테스트 통과가 필수이며, 충돌이 있으면 해결한 뒤 머지합니다.'),
  ('dohyun@company.com','로컬 개발 환경은 어떻게 세팅하나요?',TIMESTAMP '2025-03-24 13:48:36','jeonghyeon@company.com',TIMESTAMP '2025-03-25 09:00:00','JDK/Node 등 필수 런타임을 설치한 뒤 저장소 README의 로컬 실행 절차를 따르면 되며, 상세 내용은 ''개발 환경 세팅 가이드'' 문서를 참고하세요.'),
  ('dohyun@company.com','회의실은 어떻게 예약하나요?',TIMESTAMP '2025-06-11 14:01:37','jeonghyeon@company.com',TIMESTAMP '2025-06-12 09:00:00','회의실은 Google Calendar의 회의실 캘린더에서 예약하며, 예약명은 [팀명] 목적 형식으로 작성합니다. No-show가 반복되면 예약이 제한됩니다.'),
  ('dohyun@company.com','로컬 빌드가 너무 느린데 개선 방법이 있나요?',TIMESTAMP '2025-08-29 15:14:38','jeonghyeon@company.com',TIMESTAMP '2025-08-30 09:00:00','빌드 캐시(Gradle/npm)를 활용하고 불필요한 클린 빌드를 줄이면 개선됩니다. 장비 성능 문제라면 인프라팀에 사양 점검을 요청하세요.'),
  ('dohyun@company.com','단위 테스트는 어떻게 실행하나요?',TIMESTAMP '2025-11-16 16:27:39','jeonghyeon@company.com',TIMESTAMP '2025-11-17 09:00:00','백엔드는 ./gradlew test, 프론트는 npm run test로 실행하며, PR 전 로컬에서 통과를 확인한 뒤 올리는 것을 권장합니다.'),
  ('dohyun@company.com','CI가 실패하면 어떻게 대응하나요?',TIMESTAMP '2026-02-03 09:40:40','jeonghyeon@company.com',TIMESTAMP '2026-02-04 09:00:00','실패 로그를 확인해 원인을 파악하고 로컬에서 재현·수정한 뒤 다시 푸시합니다. 반복 실패 시 데브옵스 채널에 문의하세요.'),
  ('junyoung@company.com','새로운 의존성은 어떻게 추가하나요?',TIMESTAMP '2025-07-20 12:19:43','jeonghyeon@company.com',TIMESTAMP '2025-07-21 09:00:00','의존성은 담당자 검토 후 추가하며, 추가 시 버전 고정과 라이선스 확인이 필요합니다. 규모가 큰 라이브러리는 팀 논의 후 도입합니다.'),
  ('junyoung@company.com','DB 마이그레이션은 어떻게 관리하나요?',TIMESTAMP '2025-10-17 13:32:44','jeonghyeon@company.com',TIMESTAMP '2025-10-18 09:00:00','스키마 변경은 마이그레이션 스크립트로 관리하며 리뷰를 거쳐 적용합니다. 로컬은 ddl-auto로 반영되지만 운영은 스크립트로 배포합니다.'),
  ('junyoung@company.com','환경변수는 어떻게 설정하나요?',TIMESTAMP '2026-01-14 14:45:45','jeonghyeon@company.com',TIMESTAMP '2026-01-15 09:00:00','환경변수는 .env 또는 배포 환경 설정으로 주입하며, 민감한 값은 저장소에 커밋하지 않고 시크릿으로 관리합니다.'),
  ('arin@company.com','건강검진은 언제, 어떻게 받나요?',TIMESTAMP '2025-05-08 16:11:47','jeonghyeon@company.com',TIMESTAMP '2025-05-09 09:00:00','건강검진은 회사 지정 병원에서 연 1회 받을 수 있으며, 대상자는 인사팀 안내에 따라 예약 후 검진일에 다녀올 수 있습니다.'),
  ('arin@company.com','애플리케이션 로그는 어디서 확인하나요?',TIMESTAMP '2025-08-02 09:24:48','jeonghyeon@company.com',TIMESTAMP '2025-08-03 09:00:00','로컬은 콘솔에서, 운영은 로그 수집 시스템에서 확인할 수 있으며, 접근 권한이 필요하면 인프라팀에 요청하세요.'),
  ('arin@company.com','피처 플래그는 어떻게 사용하나요?',TIMESTAMP '2026-01-21 11:50:50','jeonghyeon@company.com',TIMESTAMP '2026-01-22 09:00:00','피처 플래그는 미완성·실험 기능을 조건부로 노출할 때 사용하며, 배포 후 안정화되면 플래그를 제거합니다.'),
  ('jaeyoon@company.com','유연근무제는 어떻게 운영되나요?',TIMESTAMP '2025-05-23 13:16:52','jeonghyeon@company.com',TIMESTAMP '2025-05-24 09:00:00','유연근무제는 코어타임(10~16시)을 준수하는 범위에서 출퇴근 시간을 조정할 수 있으며, 근태 시스템에 출퇴근을 기록해야 합니다.'),
  ('jaeyoon@company.com','성능 문제가 의심될 때 어떻게 확인하나요?',TIMESTAMP '2025-08-14 14:29:53','jeonghyeon@company.com',TIMESTAMP '2025-08-15 09:00:00','느린 쿼리와 API를 프로파일링으로 확인하고 인덱스·N+1 등을 점검합니다. 필요하면 모니터링 지표를 함께 분석하세요.'),
  ('jaeyoon@company.com','코드 컨벤션은 어디에 정리되어 있나요?',TIMESTAMP '2025-11-05 15:42:54','jeonghyeon@company.com',TIMESTAMP '2025-11-06 09:00:00','코드 컨벤션은 docs의 컨벤션 문서에 정리되어 있으며, 포매터·린터 설정으로 일부는 자동 적용됩니다.'),
  ('jaeyoon@company.com','develop에 머지하기 전 무엇을 확인해야 하나요?',TIMESTAMP '2026-01-27 16:55:55','jeonghyeon@company.com',TIMESTAMP '2026-01-28 09:00:00','최신 develop을 반영해 충돌을 해결하고, CI 통과와 리뷰 승인을 확인한 뒤 머지합니다.'),
  ('doyoon@company.com','복지포인트는 어디에 사용할 수 있나요?',TIMESTAMP '2025-06-09 10:21:57','jeonghyeon@company.com',TIMESTAMP '2025-06-10 09:00:00','복지포인트는 사내 복지몰과 제휴처에서 사용할 수 있으며, 연말 미사용 포인트는 소멸되니 기한 내 사용하세요.'),
  ('doyoon@company.com','테스트용 더미 데이터는 어떻게 준비하나요?',TIMESTAMP '2025-08-28 11:34:58','jeonghyeon@company.com',TIMESTAMP '2025-08-29 09:00:00','로컬은 시드 스크립트로 더미데이터를 주입하며, 재기동 시 초기화되는 환경에서는 스크립트로 다시 채웁니다.'),
  ('doyoon@company.com','이미 푸시한 커밋을 되돌리려면 어떻게 하나요?',TIMESTAMP '2025-11-15 12:47:59','jeonghyeon@company.com',TIMESTAMP '2025-11-16 09:00:00','공유된 커밋은 revert로 되돌리는 것이 안전하며, 아직 푸시 전이라면 reset을 사용합니다. 이력이 꼬였다면 팀에 공유 후 처리하세요.'),
  ('doyoon@company.com','프론트와 백엔드 API 연동은 어떻게 확인하나요?',TIMESTAMP '2026-02-03 13:00:00','jeonghyeon@company.com',TIMESTAMP '2026-02-04 09:00:00','로컬에서 프론트를 백엔드에 연결해 실제 응답을 확인하며, 프록시·CORS 설정과 응답 형식을 점검합니다.'),
  ('chaerin@company.com','차량 주차 등록은 어떻게 하나요?',TIMESTAMP '2025-10-11 15:26:02','jeonghyeon@company.com',TIMESTAMP '2025-10-12 09:00:00','주차 등록은 총무팀에 차량 번호를 등록하면 되며, 지정 주차 구역과 방문객 주차 안내는 사내 포털 공지를 참고하세요.'),
  ('chaerin@company.com','코드 리뷰는 어떤 절차로 진행되나요?',TIMESTAMP '2026-05-04 10:05:05','jeonghyeon@company.com',TIMESTAMP '2026-05-05 09:00:00','PR을 올리면 최소 1인 이상의 승인과 CI 통과가 필요하며, 리뷰 의견을 반영한 뒤 develop 브랜치로 머지합니다.'),
  ('jiwoo@company.com','PR은 어떤 조건을 충족해야 머지할 수 있나요?',TIMESTAMP '2025-10-21 11:18:06','jeonghyeon@company.com',TIMESTAMP '2025-10-22 09:00:00','PR은 리뷰어 1인 이상 승인과 CI 빌드·테스트 통과가 필수이며, 충돌이 있으면 해결한 뒤 머지합니다.'),
  ('jiwoo@company.com','점심 식대는 어떻게 지원되나요?',TIMESTAMP '2025-12-26 12:31:07','jeonghyeon@company.com',TIMESTAMP '2025-12-27 09:00:00','점심 식대는 1일 1만원 한도로 법인카드 또는 식대 포인트로 지원되며, 사용 내역은 매월 정산됩니다.'),
  ('juwon@company.com','성과 평가는 언제, 어떤 절차로 진행되나요?',TIMESTAMP '2026-03-06 09:36:12','jeonghyeon@company.com',TIMESTAMP '2026-03-07 09:00:00','성과 평가는 반기별(1월·7월)로 진행되며, 본인 자기평가 → 팀장 1차 평가 → 본부장 확정 → 피드백 면담 순으로 이루어집니다.'),
  ('soohyun@company.com','새로운 의존성은 어떻게 추가하나요?',TIMESTAMP '2025-11-08 11:02:14','jeonghyeon@company.com',TIMESTAMP '2025-11-09 09:00:00','의존성은 담당자 검토 후 추가하며, 추가 시 버전 고정과 라이선스 확인이 필요합니다. 규모가 큰 라이브러리는 팀 논의 후 도입합니다.'),
  ('soohyun@company.com','DB 마이그레이션은 어떻게 관리하나요?',TIMESTAMP '2026-01-08 12:15:15','jeonghyeon@company.com',TIMESTAMP '2026-01-09 09:00:00','스키마 변경은 마이그레이션 스크립트로 관리하며 리뷰를 거쳐 적용합니다. 로컬은 ddl-auto로 반영되지만 운영은 스크립트로 배포합니다.'),
  ('soohyun@company.com','명함은 어떻게 신청하나요?',TIMESTAMP '2026-05-11 14:41:17','jeonghyeon@company.com',TIMESTAMP '2026-05-12 09:00:00','명함은 입사 후 총무팀에 신청하며, 직급·부서 정보 확인 후 제작되어 약 3~5영업일 내 수령할 수 있습니다.'),
  ('jiyoo@company.com','API 문서는 어디서 확인하나요?',TIMESTAMP '2025-11-18 15:54:18','jeonghyeon@company.com',TIMESTAMP '2025-11-19 09:00:00','API 문서는 Swagger(/swagger-ui) 또는 API 명세서에서 확인할 수 있으며, API를 변경하면 명세도 함께 갱신합니다.'),
  ('jiyoo@company.com','예외 처리는 어떤 기준으로 하나요?',TIMESTAMP '2026-03-16 09:20:20','jeonghyeon@company.com',TIMESTAMP '2026-03-17 09:00:00','비즈니스 예외는 공통 예외 체계를 사용해 일관된 응답 형식으로 반환하며, 예상치 못한 오류는 전역 예외 핸들러에서 처리합니다.'),
  ('mjihoon@company.com','사내 동호회는 어떻게 가입하나요?',TIMESTAMP '2025-11-27 11:46:22','jeonghyeon@company.com',TIMESTAMP '2025-11-28 09:00:00','사내 동호회는 사내 포털 동호회 게시판에서 확인 후 담당자에게 신청하면 되며, 일부 활동비가 지원됩니다.'),
  ('mjihoon@company.com','코드 컨벤션은 어디에 정리되어 있나요?',TIMESTAMP '2026-05-16 14:25:25','jeonghyeon@company.com',TIMESTAMP '2026-05-17 09:00:00','코드 컨벤션은 docs의 컨벤션 문서에 정리되어 있으며, 포매터·린터 설정으로 일부는 자동 적용됩니다.'),
  ('pdogyeong@company.com','법인카드는 어떤 경우에 사용할 수 있나요?',TIMESTAMP '2026-03-20 16:51:27','jeonghyeon@company.com',TIMESTAMP '2026-03-21 09:00:00','법인카드는 업무 관련 지출(식대·비품·출장 등)에 한해 사용하며, 사용 후 영수증을 첨부해 전자결재로 사용 내역을 보고해야 합니다.'),
  ('jjimin@company.com','이미 푸시한 커밋을 되돌리려면 어떻게 하나요?',TIMESTAMP '2026-02-16 11:30:30','jeonghyeon@company.com',TIMESTAMP '2026-02-17 09:00:00','공유된 커밋은 revert로 되돌리는 것이 안전하며, 아직 푸시 전이라면 reset을 사용합니다. 이력이 꼬였다면 팀에 공유 후 처리하세요.'),
  ('jjimin@company.com','휴직은 어떻게 신청하나요?',TIMESTAMP '2026-04-30 13:56:32','jeonghyeon@company.com',TIMESTAMP '2026-05-01 09:00:00','휴직은 육아·질병·개인 사유 등이 있으며, 인사팀 상담 후 필요한 증빙과 함께 전자결재로 신청합니다. 종류별 기간과 조건이 다릅니다.'),
  ('hyujun@company.com','커밋 메시지는 어떤 형식으로 작성하나요?',TIMESTAMP '2026-04-15 16:35:35','jeonghyeon@company.com',TIMESTAMP '2026-04-16 09:00:00','커밋은 type(scope): 요약 형식을 사용합니다. 예: feat(qna): 질문 등록 API 추가. 본문에는 변경한 이유를 함께 적습니다.'),
  ('kyewon@company.com','근태를 잘못 기록했을 때 어떻게 정정하나요?',TIMESTAMP '2026-03-08 10:01:37','jeonghyeon@company.com',TIMESTAMP '2026-03-09 09:00:00','근태 오류는 근태 시스템에서 정정 요청을 상신하고 팀장 승인을 받으면 수정되며, 사유를 명확히 기재해야 합니다.'),
  ('jyuna@company.com','로컬 빌드가 너무 느린데 개선 방법이 있나요?',TIMESTAMP '2026-03-13 13:40:40','jeonghyeon@company.com',TIMESTAMP '2026-03-14 09:00:00','빌드 캐시(Gradle/npm)를 활용하고 불필요한 클린 빌드를 줄이면 개선됩니다. 장비 성능 문제라면 인프라팀에 사양 점검을 요청하세요.'),
  ('jyuna@company.com','지식문서에 없는 내용은 어디에 질문하면 되나요?',TIMESTAMP '2026-06-01 15:06:42','jeonghyeon@company.com',TIMESTAMP '2026-06-02 09:00:00','먼저 문서 검색을 통해 관련 자료가 있는지 확인한 뒤, 원하는 내용을 찾지 못한 경우 QNA에 질문을 등록하면 됩니다. 반복되는 질문은 관리자가 FAQ 문서로 전환할 수 있습니다.'),
  ('mdohyun@company.com','새로운 의존성은 어떻게 추가하나요?',TIMESTAMP '2026-06-03 10:45:45','jeonghyeon@company.com',TIMESTAMP '2026-06-04 09:00:00','의존성은 담당자 검토 후 추가하며, 추가 시 버전 고정과 라이선스 확인이 필요합니다. 규모가 큰 라이브러리는 팀 논의 후 도입합니다.'),
  ('pjunyoung@company.com','신입사원 온보딩 첫 주에는 무엇을 하나요?',TIMESTAMP '2026-04-29 12:11:47','jeonghyeon@company.com',TIMESTAMP '2026-04-30 09:00:00','첫 주는 사원증·장비 수령, 팀장 면담, 부서 OJT, 업무 배정 순으로 진행되며, 상세 일정은 온보딩 문서를 참고하세요.'),
  ('taemin@company.com','테스트/스테이징 서버에는 어떻게 접속하나요?',TIMESTAMP '2024-06-22 14:37:49','jeongyeon@company.com',TIMESTAMP '2024-06-23 09:00:00','VPN 접속 후 인프라 위키의 스테이징 접속 정보를 이용하며, 계정이 없으면 인프라팀에 요청하면 됩니다.'),
  ('taemin@company.com','배포는 어떤 절차로 진행되나요?',TIMESTAMP '2024-10-25 15:50:50','jeongyeon@company.com',TIMESTAMP '2024-10-26 09:00:00','GitHub Actions로 빌드한 뒤 스테이징에 배포하고, 승인 단계를 거쳐 운영에 반영됩니다. 상세 흐름은 인프라 위키를 참고하세요.'),
  ('taemin@company.com','노트북 등 장비는 어떻게 신청하나요?',TIMESTAMP '2025-02-27 16:03:51','jeongyeon@company.com',TIMESTAMP '2025-02-28 09:00:00','장비는 전자결재 물품 구매 요청으로 신청하며, 팀장 승인 후 IT팀 검토를 거쳐 지급됩니다.'),
  ('taemin@company.com','장비 교체는 어떤 기준으로 가능한가요?',TIMESTAMP '2025-11-04 10:29:53','jeongyeon@company.com',TIMESTAMP '2025-11-05 09:00:00','노후·고장 장비는 교체 신청이 가능하며, IT팀 점검 후 수리 불가로 판정되면 신규 장비로 교체됩니다.'),
  ('seojun@company.com','도커 이미지는 어떻게 빌드·배포하나요?',TIMESTAMP '2024-09-02 12:55:55','jeongyeon@company.com',TIMESTAMP '2024-09-03 09:00:00','이미지는 CI에서 빌드해 컨테이너 레지스트리에 푸시하며, 배포 환경에서 해당 이미지를 pull해 실행합니다.'),
  ('seojun@company.com','운영 배포 승인은 누가 하나요?',TIMESTAMP '2024-12-24 13:08:56','jeongyeon@company.com',TIMESTAMP '2024-12-25 09:00:00','운영 배포는 승인 권한이 있는 담당자가 승인하며, 승인이 완료되면 파이프라인이 운영에 반영합니다.'),
  ('seojun@company.com','급여명세서는 어디서 확인하나요?',TIMESTAMP '2025-04-16 14:21:57','jeongyeon@company.com',TIMESTAMP '2025-04-17 09:00:00','급여명세서는 ERP 급여 메뉴에서 매월 확인할 수 있으며, 공제 내역에 대한 문의는 인사팀에 하면 됩니다.'),
  ('seojun@company.com','데이터 백업은 어떻게 이루어지나요?',TIMESTAMP '2025-08-07 15:34:58','jeongyeon@company.com',TIMESTAMP '2025-08-08 09:00:00','데이터는 정기적으로 자동 백업되며, 복구가 필요한 경우 인프라팀에 요청해 복원 절차를 진행합니다.'),
  ('seojun@company.com','로그 수집 시스템에는 어떻게 접근하나요?',TIMESTAMP '2026-03-21 09:00:00','jeongyeon@company.com',TIMESTAMP '2026-03-22 09:00:00','로그는 중앙 로그 시스템에서 조회할 수 있으며, 조회 권한은 인프라팀에 요청해 부여받습니다.'),
  ('gaeun@company.com','SSL 인증서는 어떻게 갱신되나요?',TIMESTAMP '2024-10-02 10:13:01','jeongyeon@company.com',TIMESTAMP '2024-10-03 09:00:00','인증서는 만료 전 인프라팀이 갱신하며, 자동 갱신이 설정된 경우 별도 조치 없이 유지됩니다.'),
  ('gaeun@company.com','워크숍 참석은 필수인가요?',TIMESTAMP '2025-01-18 11:26:02','jeongyeon@company.com',TIMESTAMP '2025-01-19 09:00:00','부서 워크숍은 팀 일정에 따라 진행되며, 참석 여부와 일정은 팀장 공지에 따릅니다. 불참이 필요하면 사전에 팀장과 협의하세요.'),
  ('gaeun@company.com','디스크 용량이 부족할 때는 어떻게 하나요?',TIMESTAMP '2025-05-06 12:39:03','jeongyeon@company.com',TIMESTAMP '2025-05-07 09:00:00','불필요한 파일을 정리한 뒤에도 용량이 부족하면 인프라팀에 증설을 요청하세요.'),
  ('gaeun@company.com','스토리지 증설은 어떻게 요청하나요?',TIMESTAMP '2025-08-22 13:52:04','jeongyeon@company.com',TIMESTAMP '2025-08-23 09:00:00','스토리지 증설은 사유와 예상 용량을 담아 인프라팀에 요청하면 검토 후 증설됩니다.'),
  ('gaeun@company.com','오토스케일은 어떻게 동작하나요?',TIMESTAMP '2025-12-08 14:05:05','jeongyeon@company.com',TIMESTAMP '2025-12-09 09:00:00','트래픽 지표에 따라 인스턴스가 자동으로 증감하며, 임계값과 최소/최대 대수는 인프라팀이 관리합니다.'),
  ('seoyoon@company.com','연차는 입사 후 언제부터 사용할 수 있나요?',TIMESTAMP '2025-01-30 16:31:07','jeongyeon@company.com',TIMESTAMP '2025-01-31 09:00:00','연차는 입사일 기준으로 발생하며, 전자결재의 휴가 신청 메뉴에서 신청 후 팀장 승인을 받으면 사용할 수 있습니다. 입사 1년 미만은 매월 1일씩 발생합니다.'),
  ('seoyoon@company.com','컨테이너 레지스트리 접근 권한은 어떻게 받나요?',TIMESTAMP '2025-04-28 09:44:08','jeongyeon@company.com',TIMESTAMP '2025-04-29 09:00:00','레지스트리 접근은 인프라팀에 요청하면 계정에 push/pull 권한이 부여됩니다.'),
  ('seoyoon@company.com','장애 알림은 어떻게 설정하나요?',TIMESTAMP '2025-07-25 10:57:09','jeongyeon@company.com',TIMESTAMP '2025-07-26 09:00:00','알림은 모니터링 지표 임계값을 기준으로 설정하며, Slack 등으로 전달되도록 인프라팀과 함께 구성합니다.'),
  ('seoyoon@company.com','서버 재시작이 필요할 때는 누구에게 요청하나요?',TIMESTAMP '2025-10-21 11:10:10','jeongyeon@company.com',TIMESTAMP '2025-10-22 09:00:00','운영 서버 재시작은 영향 범위를 확인한 뒤 인프라팀에 요청하며, 긴급 시 핫라인으로 연락합니다.'),
  ('seoyoon@company.com','반차를 사용하려면 어떤 절차를 따라야 하나요?',TIMESTAMP '2026-04-15 13:36:12','jeongyeon@company.com',TIMESTAMP '2026-04-16 09:00:00','반차는 전자결재 휴가 신청에서 오전/오후를 선택해 상신하고 팀장 승인 후 사용합니다. 사용일 최소 1일 전 신청을 권장합니다.'),
  ('hajun@company.com','배포 파이프라인 구조가 궁금합니다.',TIMESTAMP '2025-05-19 15:02:14','jeongyeon@company.com',TIMESTAMP '2025-05-20 09:00:00','빌드 → 테스트 → 스테이징 배포 → 승인 → 운영 배포 순으로 구성되며, 각 단계는 CI/CD에서 자동화되어 있습니다.'),
  ('hajun@company.com','스테이징 없이 바로 운영에 배포되나요?',TIMESTAMP '2025-08-11 16:15:15','jeongyeon@company.com',TIMESTAMP '2025-08-12 09:00:00','스테이징은 자동 배포되지만 운영은 반드시 승인 단계를 거쳐야 배포됩니다.'),
  ('hajun@company.com','지급받은 장비는 언제 반납하나요?',TIMESTAMP '2025-11-02 09:28:16','jeongyeon@company.com',TIMESTAMP '2025-11-03 09:00:00','퇴사 또는 교체 시 지급 장비를 IT팀에 반납하며, 자산 확인 후 반납 처리됩니다.'),
  ('hajun@company.com','반차 사용 시 전자결재 서류는 언제까지 올려야 하나요?',TIMESTAMP '2026-01-25 10:41:17','jeongyeon@company.com',TIMESTAMP '2026-01-26 09:00:00','반차 신청은 사용일 전날까지 전자결재로 상신해야 하며, 승인 완료 후 근태 시스템에 자동 반영됩니다.'),
  ('jeongmin@company.com','서버 타임존은 어떻게 설정되어 있나요?',TIMESTAMP '2025-03-22 12:07:19','jeongyeon@company.com',TIMESTAMP '2025-03-23 09:00:00','서버는 표준 타임존으로 설정되어 있으며, 애플리케이션에서 별도 처리가 필요하면 인프라팀 설정을 확인하세요.'),
  ('jeongmin@company.com','배포는 어떤 절차로 진행되나요?',TIMESTAMP '2025-08-28 14:33:21','jeongyeon@company.com',TIMESTAMP '2025-08-29 09:00:00','GitHub Actions로 빌드한 뒤 스테이징에 배포하고, 승인 단계를 거쳐 운영에 반영됩니다. 상세 흐름은 인프라 위키를 참고하세요.'),
  ('jeongmin@company.com','경조사 지원은 어떻게 신청하나요?',TIMESTAMP '2025-11-15 15:46:22','jeongyeon@company.com',TIMESTAMP '2025-11-16 09:00:00','경조사 지원은 총무팀에 경조사 신청서와 증빙 서류를 제출하면 되며, 경조 휴가와 경조금이 함께 처리됩니다.'),
  ('minseo@company.com','서비스 모니터링 대시보드는 어디서 보나요?',TIMESTAMP '2025-06-25 10:25:25','jeongyeon@company.com',TIMESTAMP '2025-06-26 09:00:00','서비스 상태는 모니터링 대시보드에서 확인할 수 있으며, 접근 권한이 필요하면 인프라팀에 요청하세요.'),
  ('minseo@company.com','도커 이미지는 어떻게 빌드·배포하나요?',TIMESTAMP '2025-09-09 11:38:26','jeongyeon@company.com',TIMESTAMP '2025-09-10 09:00:00','이미지는 CI에서 빌드해 컨테이너 레지스트리에 푸시하며, 배포 환경에서 해당 이미지를 pull해 실행합니다.'),
  ('hyunwoo@company.com','스케줄(크론) 작업은 어떻게 등록하나요?',TIMESTAMP '2025-07-11 15:30:30','jeongyeon@company.com',TIMESTAMP '2025-07-12 09:00:00','배치·스케줄 작업은 인프라팀과 협의해 등록하며, 실행 주기와 실패 알림 설정을 함께 정의합니다.'),
  ('hyunwoo@company.com','로그 수집 시스템에는 어떻게 접근하나요?',TIMESTAMP '2025-09-22 16:43:31','jeongyeon@company.com',TIMESTAMP '2025-09-23 09:00:00','로그는 중앙 로그 시스템에서 조회할 수 있으며, 조회 권한은 인프라팀에 요청해 부여받습니다.'),
  ('hyunwoo@company.com','교육비는 얼마까지 지원받을 수 있나요?',TIMESTAMP '2025-12-04 09:56:32','jeongyeon@company.com',TIMESTAMP '2025-12-05 09:00:00','교육비는 연 50만원 한도로 지원되며, 팀장 승인 후 전자결재로 신청하고 수료증과 영수증을 제출하면 정산됩니다.'),
  ('bomin@company.com','스토리지 증설은 어떻게 요청하나요?',TIMESTAMP '2025-07-27 12:35:35','jeongyeon@company.com',TIMESTAMP '2025-07-28 09:00:00','스토리지 증설은 사유와 예상 용량을 담아 인프라팀에 요청하면 검토 후 증설됩니다.'),
  ('bomin@company.com','오토스케일은 어떻게 동작하나요?',TIMESTAMP '2025-10-05 13:48:36','jeongyeon@company.com',TIMESTAMP '2025-10-06 09:00:00','트래픽 지표에 따라 인스턴스가 자동으로 증감하며, 임계값과 최소/최대 대수는 인프라팀이 관리합니다.'),
  ('bomin@company.com','출장 신청과 정산은 어떻게 하나요?',TIMESTAMP '2025-12-14 14:01:37','jeongyeon@company.com',TIMESTAMP '2025-12-15 09:00:00','출장은 전자결재 출장 신청서로 사전 상신하고, 복귀 후 3일 이내 교통비·숙박비 영수증을 첨부해 정산합니다.'),
  ('sua@company.com','장애 알림은 어떻게 설정하나요?',TIMESTAMP '2025-08-11 09:40:40','jeongyeon@company.com',TIMESTAMP '2025-08-12 09:00:00','알림은 모니터링 지표 임계값을 기준으로 설정하며, Slack 등으로 전달되도록 인프라팀과 함께 구성합니다.'),
  ('sua@company.com','회의실은 어떻게 예약하나요?',TIMESTAMP '2025-12-23 11:06:42','jeongyeon@company.com',TIMESTAMP '2025-12-24 09:00:00','회의실은 Google Calendar의 회의실 캘린더에서 예약하며, 예약명은 [팀명] 목적 형식으로 작성합니다. No-show가 반복되면 예약이 제한됩니다.'),
  ('sunwoo@company.com','배포 파이프라인 구조가 궁금합니다.',TIMESTAMP '2025-08-27 14:45:45','jeongyeon@company.com',TIMESTAMP '2025-08-28 09:00:00','빌드 → 테스트 → 스테이징 배포 → 승인 → 운영 배포 순으로 구성되며, 각 단계는 CI/CD에서 자동화되어 있습니다.'),
  ('sunwoo@company.com','스테이징 없이 바로 운영에 배포되나요?',TIMESTAMP '2025-10-30 15:58:46','jeongyeon@company.com',TIMESTAMP '2025-10-31 09:00:00','스테이징은 자동 배포되지만 운영은 반드시 승인 단계를 거쳐야 배포됩니다.'),
  ('sunwoo@company.com','사원증을 분실하면 어떻게 재발급받나요?',TIMESTAMP '2026-01-02 16:11:47','jeongyeon@company.com',TIMESTAMP '2026-01-03 09:00:00','사원증 분실 시 총무팀(1층 안내데스크)에 재발급을 신청하며, 재발급 전까지는 임시 출입증을 이용할 수 있습니다.'),
  ('sejin@company.com','서버 타임존은 어떻게 설정되어 있나요?',TIMESTAMP '2025-12-07 11:50:50','jeongyeon@company.com',TIMESTAMP '2025-12-08 09:00:00','서버는 표준 타임존으로 설정되어 있으며, 애플리케이션에서 별도 처리가 필요하면 인프라팀 설정을 확인하세요.'),
  ('sejin@company.com','건강검진은 언제, 어떻게 받나요?',TIMESTAMP '2026-03-25 13:16:52','jeongyeon@company.com',TIMESTAMP '2026-03-26 09:00:00','건강검진은 회사 지정 병원에서 연 1회 받을 수 있으며, 대상자는 인사팀 안내에 따라 예약 후 검진일에 다녀올 수 있습니다.'),
  ('daeun@company.com','노트북 등 장비는 어떻게 신청하나요?',TIMESTAMP '2025-12-16 15:42:54','jeongyeon@company.com',TIMESTAMP '2025-12-17 09:00:00','장비는 전자결재 물품 구매 요청으로 신청하며, 팀장 승인 후 IT팀 검토를 거쳐 지급됩니다.'),
  ('daeun@company.com','장비 교체는 어떤 기준으로 가능한가요?',TIMESTAMP '2026-02-06 16:55:55','jeongyeon@company.com',TIMESTAMP '2026-02-07 09:00:00','노후·고장 장비는 교체 신청이 가능하며, IT팀 점검 후 수리 불가로 판정되면 신규 장비로 교체됩니다.'),
  ('daeun@company.com','유연근무제는 어떻게 운영되나요?',TIMESTAMP '2026-05-21 10:21:57','jeongyeon@company.com',TIMESTAMP '2026-05-22 09:00:00','유연근무제는 코어타임(10~16시)을 준수하는 범위에서 출퇴근 시간을 조정할 수 있으며, 근태 시스템에 출퇴근을 기록해야 합니다.'),
  ('junhyeok@company.com','데이터 백업은 어떻게 이루어지나요?',TIMESTAMP '2026-04-04 13:00:00','jeongyeon@company.com',TIMESTAMP '2026-04-05 09:00:00','데이터는 정기적으로 자동 백업되며, 복구가 필요한 경우 인프라팀에 요청해 복원 절차를 진행합니다.'),
  ('heewon@company.com','복지포인트는 어디에 사용할 수 있나요?',TIMESTAMP '2026-01-04 15:26:02','jeongyeon@company.com',TIMESTAMP '2026-01-05 09:00:00','복지포인트는 사내 복지몰과 제휴처에서 사용할 수 있으며, 연말 미사용 포인트는 소멸되니 기한 내 사용하세요.'),
  ('heewon@company.com','디스크 용량이 부족할 때는 어떻게 하나요?',TIMESTAMP '2026-05-25 10:05:05','jeongyeon@company.com',TIMESTAMP '2026-05-26 09:00:00','불필요한 파일을 정리한 뒤에도 용량이 부족하면 인프라팀에 증설을 요청하세요.'),
  ('nayeon@company.com','차량 주차 등록은 어떻게 하나요?',TIMESTAMP '2026-02-27 12:31:07','jeongyeon@company.com',TIMESTAMP '2026-02-28 09:00:00','주차 등록은 총무팀에 차량 번호를 등록하면 되며, 지정 주차 구역과 방문객 주차 안내는 사내 포털 공지를 참고하세요.'),
  ('ktaemin@company.com','컨테이너 레지스트리 접근 권한은 어떻게 받나요?',TIMESTAMP '2026-01-23 15:10:10','jeongyeon@company.com',TIMESTAMP '2026-01-24 09:00:00','레지스트리 접근은 인프라팀에 요청하면 계정에 push/pull 권한이 부여됩니다.'),
  ('ktaemin@company.com','점심 식대는 어떻게 지원되나요?',TIMESTAMP '2026-04-18 09:36:12','jeongyeon@company.com',TIMESTAMP '2026-04-19 09:00:00','점심 식대는 1일 1만원 한도로 법인카드 또는 식대 포인트로 지원되며, 사용 내역은 매월 정산됩니다.'),
  ('lseojun@company.com','메모리 부족 경고가 뜨면 어떻게 대응하나요?',TIMESTAMP '2026-05-03 12:15:15','jeongyeon@company.com',TIMESTAMP '2026-05-04 09:00:00','메모리 사용량을 점검해 누수나 과다 사용을 확인하고, 필요하면 인프라팀에 증설 또는 스케일 조정을 요청합니다.'),
  ('sgaeun@company.com','성과 평가는 언제, 어떤 절차로 진행되나요?',TIMESTAMP '2026-04-04 14:41:17','jeongyeon@company.com',TIMESTAMP '2026-04-05 09:00:00','성과 평가는 반기별(1월·7월)로 진행되며, 본인 자기평가 → 팀장 1차 평가 → 본부장 확정 → 피드백 면담 순으로 이루어집니다.'),
  ('sseoyoon@company.com','배포 이력은 어디서 확인하나요?',TIMESTAMP '2026-04-09 09:20:20','jeongyeon@company.com',TIMESTAMP '2026-04-10 09:00:00','배포 이력은 CI/CD 파이프라인 기록에서 확인할 수 있으며, 접근이 필요하면 인프라팀에 요청하세요.'),
  ('sseoyoon@company.com','명함은 어떻게 신청하나요?',TIMESTAMP '2026-06-10 11:46:22','jeongyeon@company.com',TIMESTAMP '2026-06-11 09:00:00','명함은 입사 후 총무팀에 신청하며, 직급·부서 정보 확인 후 제작되어 약 3~5영업일 내 수령할 수 있습니다.'),
  ('ko.hajun@company.com','노트북 등 장비는 어떻게 신청하나요?',TIMESTAMP '2026-06-12 14:25:25','jeongyeon@company.com',TIMESTAMP '2026-06-13 09:00:00','장비는 전자결재 물품 구매 요청으로 신청하며, 팀장 승인 후 IT팀 검토를 거쳐 지급됩니다.'),
  ('lee.jeongmin@company.com','사내 동호회는 어떻게 가입하나요?',TIMESTAMP '2026-05-17 16:51:27','jeongyeon@company.com',TIMESTAMP '2026-05-18 09:00:00','사내 동호회는 사내 포털 동호회 게시판에서 확인 후 담당자에게 신청하면 되며, 일부 활동비가 지원됩니다.'),
  ('kminseo@company.com','운영 배포 승인은 누가 하나요?',TIMESTAMP '2026-05-21 11:30:30','jeongyeon@company.com',TIMESTAMP '2026-05-22 09:00:00','운영 배포는 승인 권한이 있는 담당자가 승인하며, 승인이 완료되면 파이프라인이 운영에 반영합니다.'),
  ('lhyunwoo@company.com','법인카드는 어떤 경우에 사용할 수 있나요?',TIMESTAMP '2026-04-30 13:56:32','jeongyeon@company.com',TIMESTAMP '2026-05-01 09:00:00','법인카드는 업무 관련 지출(식대·비품·출장 등)에 한해 사용하며, 사용 후 영수증을 첨부해 전자결재로 사용 내역을 보고해야 합니다.'),
  ('chaewon@company.com','비밀번호는 얼마나 자주 변경해야 하나요?',TIMESTAMP '2024-08-25 16:35:35','yeondong@company.com',TIMESTAMP '2024-08-26 09:00:00','비밀번호는 90일마다 변경해야 하며, 영문·숫자·특수문자 조합 8자 이상이어야 하고 최근 3회 사용한 비밀번호는 재사용할 수 없습니다.'),
  ('chaewon@company.com','MFA(2차 인증)는 어떻게 설정하나요?',TIMESTAMP '2024-12-17 09:48:36','yeondong@company.com',TIMESTAMP '2024-12-18 09:00:00','보안 포털에서 OTP 앱을 등록하면 되며, 주요 시스템 접근 시 MFA가 필수입니다.'),
  ('chaewon@company.com','계정 권한은 어떻게 요청하나요?',TIMESTAMP '2025-08-03 11:14:38','yeondong@company.com',TIMESTAMP '2025-08-04 09:00:00','필요한 시스템 권한은 사유를 담아 신청하면 승인권자 검토 후 부여되며, 최소 권한 원칙에 따라 관리됩니다.'),
  ('chaewon@company.com','노트북 디스크 암호화는 필수인가요?',TIMESTAMP '2025-11-25 12:27:39','yeondong@company.com',TIMESTAMP '2025-11-26 09:00:00','지급 노트북은 디스크 암호화가 필수이며, 미설정 시 보안팀에서 설정을 안내합니다.'),
  ('chaewon@company.com','퇴사자 계정은 언제 비활성화되나요?',TIMESTAMP '2026-03-19 13:40:40','yeondong@company.com',TIMESTAMP '2026-03-20 09:00:00','퇴사 처리 당일 계정이 비활성화되고 관련 권한이 즉시 회수됩니다.'),
  ('woojin@company.com','피싱 메일을 받으면 어떻게 해야 하나요?',TIMESTAMP '2024-12-31 14:53:41','yeondong@company.com',TIMESTAMP '2025-01-01 09:00:00','의심 메일은 클릭·회신하지 말고 보안팀에 신고하며, 첨부파일 실행이나 링크 접속을 삼가야 합니다.'),
  ('woojin@company.com','근태를 잘못 기록했을 때 어떻게 정정하나요?',TIMESTAMP '2025-04-03 15:06:42','yeondong@company.com',TIMESTAMP '2025-04-04 09:00:00','근태 오류는 근태 시스템에서 정정 요청을 상신하고 팀장 승인을 받으면 수정되며, 사유를 명확히 기재해야 합니다.'),
  ('woojin@company.com','보안 사고가 발생하면 어떻게 신고하나요?',TIMESTAMP '2025-07-05 16:19:43','yeondong@company.com',TIMESTAMP '2025-07-06 09:00:00','사고 발생 즉시 보안팀 핫라인(24시간)에 연락하고 관련 시스템 접근을 중단한 뒤, 발생 시각·범위를 정리해 보고합니다.'),
  ('woojin@company.com','USB 등 외부 저장장치를 사용할 수 있나요?',TIMESTAMP '2026-01-07 10:45:45','yeondong@company.com',TIMESTAMP '2026-01-08 09:00:00','외부 저장장치 사용은 원칙적으로 제한되며, 필요 시 보안팀 승인을 받아 허용된 매체만 사용할 수 있습니다.'),
  ('dahyun@company.com','지식문서에 없는 내용은 어디에 질문하면 되나요?',TIMESTAMP '2025-01-30 12:11:47','yeondong@company.com',TIMESTAMP '2025-01-31 09:00:00','먼저 문서 검색을 통해 관련 자료가 있는지 확인한 뒤, 원하는 내용을 찾지 못한 경우 QNA에 질문을 등록하면 됩니다. 반복되는 질문은 관리자가 FAQ 문서로 전환할 수 있습니다.'),
  ('dahyun@company.com','SSO는 어떻게 연동되나요?',TIMESTAMP '2025-04-28 13:24:48','yeondong@company.com',TIMESTAMP '2025-04-29 09:00:00','사내 시스템은 SSO로 통합 인증되며, 최초 로그인 시 계정을 연동하면 단일 로그인으로 접근할 수 있습니다.'),
  ('dahyun@company.com','접근 권한은 어떤 원칙으로 관리되나요?',TIMESTAMP '2025-07-25 14:37:49','yeondong@company.com',TIMESTAMP '2025-07-26 09:00:00','접근 권한은 최소 권한 원칙에 따라 부여되며, 정기적으로 권한을 재검토해 불필요한 권한을 회수합니다.'),
  ('dahyun@company.com','로그 감사는 어떤 기준으로 이루어지나요?',TIMESTAMP '2025-10-21 15:50:50','yeondong@company.com',TIMESTAMP '2025-10-22 09:00:00','주요 시스템의 접근·변경 이력은 감사 로그로 기록되며, 정기 점검을 통해 이상 행위를 확인합니다.'),
  ('dahyun@company.com','신입사원 온보딩 첫 주에는 무엇을 하나요?',TIMESTAMP '2026-04-15 09:16:52','yeondong@company.com',TIMESTAMP '2026-04-16 09:00:00','첫 주는 사원증·장비 수령, 팀장 면담, 부서 OJT, 업무 배정 순으로 진행되며, 상세 일정은 온보딩 문서를 참고하세요.'),
  ('eunseo@company.com','개인정보는 어떻게 취급해야 하나요?',TIMESTAMP '2025-07-14 10:29:53','yeondong@company.com',TIMESTAMP '2025-07-15 09:00:00','개인정보는 업무 목적 범위에서만 접근·처리하며, 외부 유출과 무단 저장이 금지됩니다. 관련 문의는 보안팀에 하면 됩니다.'),
  ('eunseo@company.com','백신(보안 프로그램)은 필수로 설치해야 하나요?',TIMESTAMP '2025-09-25 11:42:54','yeondong@company.com',TIMESTAMP '2025-09-26 09:00:00','업무용 PC에는 지정 백신 설치가 필수이며, 실시간 검사와 최신 업데이트 유지가 필요합니다.'),
  ('eunseo@company.com','API 키 등 시크릿은 어떻게 관리하나요?',TIMESTAMP '2025-12-06 12:55:55','yeondong@company.com',TIMESTAMP '2025-12-07 09:00:00','API 키·시크릿은 코드에 하드코딩하지 않고 시크릿 저장소로 관리하며, 유출 시 즉시 폐기·재발급합니다.'),
  ('eunseo@company.com','사내 공지는 어디서 확인하나요?',TIMESTAMP '2026-04-30 14:21:57','yeondong@company.com',TIMESTAMP '2026-05-01 09:00:00','사내 공지는 대시보드 공지사항과 Slack #전체공지 채널에서 확인할 수 있으며, 긴급 공지는 별도 알림으로 전달됩니다.'),
  ('minjae@company.com','계정이 잠겼을 때는 어떻게 해제하나요?',TIMESTAMP '2025-10-15 16:47:59','yeondong@company.com',TIMESTAMP '2025-10-16 09:00:00','계정 잠금은 비밀번호 오류 등으로 발생하며, 본인 확인 후 보안팀 또는 셀프 서비스로 해제할 수 있습니다.'),
  ('minjae@company.com','재직 중 알게 된 기밀은 퇴직 후에도 지켜야 하나요?',TIMESTAMP '2025-12-22 09:00:00','yeondong@company.com',TIMESTAMP '2025-12-23 09:00:00','네, 업무상 알게 된 비밀은 재직 중은 물론 퇴직 후에도 누설해서는 안 됩니다.'),
  ('minjae@company.com','급여명세서는 어디서 확인하나요?',TIMESTAMP '2026-05-05 11:26:02','yeondong@company.com',TIMESTAMP '2026-05-06 09:00:00','급여명세서는 ERP 급여 메뉴에서 매월 확인할 수 있으며, 공제 내역에 대한 문의는 인사팀에 하면 됩니다.'),
  ('soyeon@company.com','비밀번호를 잊어버리면 어떻게 재설정하나요?',TIMESTAMP '2025-09-03 12:39:03','yeondong@company.com',TIMESTAMP '2025-09-04 09:00:00','로그인 화면의 비밀번호 재설정 또는 보안 포털을 통해 본인 인증 후 재설정할 수 있습니다.'),
  ('soyeon@company.com','외부 협력사에 계정을 제공해야 할 때는 어떻게 하나요?',TIMESTAMP '2025-11-04 13:52:04','yeondong@company.com',TIMESTAMP '2025-11-05 09:00:00','외부 계정은 최소 권한과 기간 제한으로 발급하며, 사용이 끝나면 즉시 비활성화합니다. 발급에는 보안팀 승인이 필요합니다.'),
  ('soyeon@company.com','자리를 비울 때 화면 잠금은 꼭 해야 하나요?',TIMESTAMP '2026-01-06 14:05:05','yeondong@company.com',TIMESTAMP '2026-01-07 09:00:00','자리를 비울 때는 반드시 화면을 잠그고, 퇴근 시에는 PC 잠금과 민감 문서 보관을 확인해야 합니다.'),
  ('soyeon@company.com','워크숍 참석은 필수인가요?',TIMESTAMP '2026-05-10 16:31:07','yeondong@company.com',TIMESTAMP '2026-05-11 09:00:00','부서 워크숍은 팀 일정에 따라 진행되며, 참석 여부와 일정은 팀장 공지에 따릅니다. 불참이 필요하면 사전에 팀장과 협의하세요.'),
  ('yerin@company.com','MFA(2차 인증)는 어떻게 설정하나요?',TIMESTAMP '2025-12-10 09:44:08','yeondong@company.com',TIMESTAMP '2025-12-11 09:00:00','보안 포털에서 OTP 앱을 등록하면 되며, 주요 시스템 접근 시 MFA가 필수입니다.'),
  ('yerin@company.com','노트북 디스크 암호화는 필수인가요?',TIMESTAMP '2026-03-27 11:10:10','yeondong@company.com',TIMESTAMP '2026-03-28 09:00:00','지급 노트북은 디스크 암호화가 필수이며, 미설정 시 보안팀에서 설정을 안내합니다.'),
  ('jeongwoo@company.com','연차는 입사 후 언제부터 사용할 수 있나요?',TIMESTAMP '2025-12-26 13:36:12','yeondong@company.com',TIMESTAMP '2025-12-27 09:00:00','연차는 입사일 기준으로 발생하며, 전자결재의 휴가 신청 메뉴에서 신청 후 팀장 승인을 받으면 사용할 수 있습니다. 입사 1년 미만은 매월 1일씩 발생합니다.'),
  ('jeongwoo@company.com','사내 문서를 외부에 공유해도 되나요?',TIMESTAMP '2026-05-23 16:15:15','yeondong@company.com',TIMESTAMP '2026-05-24 09:00:00','기밀 문서는 외부 공유가 금지되며, 공개 등급 문서만 승인 절차를 거쳐 공유할 수 있습니다.'),
  ('minjun@company.com','반차를 사용하려면 어떤 절차를 따라야 하나요?',TIMESTAMP '2026-02-25 10:41:17','yeondong@company.com',TIMESTAMP '2026-02-26 09:00:00','반차는 전자결재 휴가 신청에서 오전/오후를 선택해 상신하고 팀장 승인 후 사용합니다. 사용일 최소 1일 전 신청을 권장합니다.'),
  ('jiwon@company.com','접근 권한은 어떤 원칙으로 관리되나요?',TIMESTAMP '2026-01-25 13:20:20','yeondong@company.com',TIMESTAMP '2026-01-26 09:00:00','접근 권한은 최소 권한 원칙에 따라 부여되며, 정기적으로 권한을 재검토해 불필요한 권한을 회수합니다.'),
  ('jiwon@company.com','반차 사용 시 전자결재 서류는 언제까지 올려야 하나요?',TIMESTAMP '2026-04-19 15:46:22','yeondong@company.com',TIMESTAMP '2026-04-20 09:00:00','반차 신청은 사용일 전날까지 전자결재로 상신해야 하며, 승인 완료 후 근태 시스템에 자동 반영됩니다.'),
  ('seoyeon@company.com','백신(보안 프로그램)은 필수로 설치해야 하나요?',TIMESTAMP '2026-03-20 10:25:25','yeondong@company.com',TIMESTAMP '2026-03-21 09:00:00','업무용 PC에는 지정 백신 설치가 필수이며, 실시간 검사와 최신 업데이트 유지가 필요합니다.'),
  ('seoyeon@company.com','경조사 지원은 어떻게 신청하나요?',TIMESTAMP '2026-06-04 12:51:27','yeondong@company.com',TIMESTAMP '2026-06-05 09:00:00','경조사 지원은 총무팀에 경조사 신청서와 증빙 서류를 제출하면 되며, 경조 휴가와 경조금이 함께 처리됩니다.'),
  ('siwoo@company.com','계정이 잠겼을 때는 어떻게 해제하나요?',TIMESTAMP '2026-06-09 15:30:30','yeondong@company.com',TIMESTAMP '2026-06-10 09:00:00','계정 잠금은 비밀번호 오류 등으로 발생하며, 본인 확인 후 보안팀 또는 셀프 서비스로 해제할 수 있습니다.'),
  ('eunji@company.com','재택근무는 어떤 절차로 신청하나요?',TIMESTAMP '2026-05-14 09:56:32','yeondong@company.com',TIMESTAMP '2026-05-15 09:00:00','재택근무는 전자결재로 사전 신청 후 팀장 승인을 받아 진행하며, 코어타임(10~16시) 근무와 사내 메신저 상태 유지가 필요합니다.'),
  ('hayoon@company.com','외부 협력사에 계정을 제공해야 할 때는 어떻게 하나요?',TIMESTAMP '2026-05-20 12:35:35','yeondong@company.com',TIMESTAMP '2026-05-21 09:00:00','외부 계정은 최소 권한과 기간 제한으로 발급하며, 사용이 끝나면 즉시 비활성화합니다. 발급에는 보안팀 승인이 필요합니다.'),
  ('junwoo@company.com','교육비는 얼마까지 지원받을 수 있나요?',TIMESTAMP '2026-05-02 14:01:37','yeondong@company.com',TIMESTAMP '2026-05-03 09:00:00','교육비는 연 50만원 한도로 지원되며, 팀장 승인 후 전자결재로 신청하고 수료증과 영수증을 제출하면 정산됩니다.'),
  ('yujin@company.com','계정 권한은 어떻게 요청하나요?',TIMESTAMP '2026-05-18 09:40:40','yeondong@company.com',TIMESTAMP '2026-05-19 09:00:00','필요한 시스템 권한은 사유를 담아 신청하면 승인권자 검토 후 부여되며, 최소 권한 원칙에 따라 관리됩니다.'),
  ('schaewon@company.com','출장 신청과 정산은 어떻게 하나요?',TIMESTAMP '2026-05-26 11:06:42','yeondong@company.com',TIMESTAMP '2026-05-27 09:00:00','출장은 전자결재 출장 신청서로 사전 상신하고, 복귀 후 3일 이내 교통비·숙박비 영수증을 첨부해 정산합니다.'),
  ('soyoon@company.com','사내 VPN은 어디서 받아 설치하나요?',TIMESTAMP '2024-07-23 14:29:53','buyeon@company.com',TIMESTAMP '2024-07-24 09:00:00','VPN 클라이언트는 사내 포털 다운로드 센터에서 받을 수 있으며, 설치 후 사번 계정으로 로그인합니다.'),
  ('soyoon@company.com','사내망에는 어떻게 접속하나요?',TIMESTAMP '2025-03-20 16:55:55','buyeon@company.com',TIMESTAMP '2025-03-21 09:00:00','사내망은 사무실 유선/사내 WiFi 또는 VPN을 통해 접속하며, 접속 정보는 총무팀·인프라팀 안내를 따릅니다.'),
  ('soyoon@company.com','사내 WiFi 비밀번호는 어디서 확인하나요?',TIMESTAMP '2025-07-17 09:08:56','buyeon@company.com',TIMESTAMP '2025-07-18 09:00:00','WiFi 접속 정보는 사내 포털 공지 또는 총무팀에서 확인할 수 있습니다.'),
  ('soyoon@company.com','건강검진은 언제, 어떻게 받나요?',TIMESTAMP '2025-11-14 10:21:57','buyeon@company.com',TIMESTAMP '2025-11-15 09:00:00','건강검진은 회사 지정 병원에서 연 1회 받을 수 있으며, 대상자는 인사팀 안내에 따라 예약 후 검진일에 다녀올 수 있습니다.'),
  ('gyumin@company.com','특정 포트를 열어야 할 때는 어떻게 요청하나요?',TIMESTAMP '2024-11-01 12:47:59','buyeon@company.com',TIMESTAMP '2024-11-02 09:00:00','포트 오픈은 용도·대상·기간을 명시해 인프라팀에 요청하며, 보안 검토를 거쳐 허용됩니다.'),
  ('gyumin@company.com','프록시 설정은 어떻게 하나요?',TIMESTAMP '2025-02-12 13:00:00','buyeon@company.com',TIMESTAMP '2025-02-13 09:00:00','사내 프록시 설정 값은 인프라팀 안내에 따라 적용하며, 일부 도구는 별도 예외 설정이 필요할 수 있습니다.'),
  ('gyumin@company.com','유연근무제는 어떻게 운영되나요?',TIMESTAMP '2025-09-06 15:26:02','buyeon@company.com',TIMESTAMP '2025-09-07 09:00:00','유연근무제는 코어타임(10~16시)을 준수하는 범위에서 출퇴근 시간을 조정할 수 있으며, 근태 시스템에 출퇴근을 기록해야 합니다.'),
  ('gyumin@company.com','네트워크가 느릴 때는 어떻게 확인하나요?',TIMESTAMP '2025-12-18 16:39:03','buyeon@company.com',TIMESTAMP '2025-12-19 09:00:00','속도 테스트로 상태를 확인하고 유선 연결을 시도해 보며, 광범위한 지연은 인프라팀에 로그와 함께 신고합니다.'),
  ('yejun@company.com','네트워크 장애가 발생하면 어디에 신고하나요?',TIMESTAMP '2024-12-01 10:05:05','buyeon@company.com',TIMESTAMP '2024-12-02 09:00:00','네트워크 장애는 인프라팀에 증상과 발생 시각을 함께 신고하며, 긴급 시 핫라인으로 연락합니다.'),
  ('yejun@company.com','사내 고정 IP가 필요할 때는 어떻게 요청하나요?',TIMESTAMP '2025-03-09 11:18:06','buyeon@company.com',TIMESTAMP '2025-03-10 09:00:00','고정 IP는 사유와 대상 장비를 정리해 인프라팀에 요청하면 할당받을 수 있습니다.'),
  ('yejun@company.com','복지포인트는 어디에 사용할 수 있나요?',TIMESTAMP '2025-06-15 12:31:07','buyeon@company.com',TIMESTAMP '2025-06-16 09:00:00','복지포인트는 사내 복지몰과 제휴처에서 사용할 수 있으며, 연말 미사용 포인트는 소멸되니 기한 내 사용하세요.'),
  ('yejun@company.com','방화벽 허용 요청은 얼마나 걸리나요?',TIMESTAMP '2026-04-05 15:10:10','buyeon@company.com',TIMESTAMP '2026-04-06 09:00:00','방화벽 허용은 보안 검토가 포함되어 통상 수 영업일이 소요되며, 긴급 건은 사유를 명시해 우선 처리를 요청할 수 있습니다.'),
  ('hyewon@company.com','패킷 손실이 의심될 때는 어떻게 확인하나요?',TIMESTAMP '2025-04-30 16:23:11','buyeon@company.com',TIMESTAMP '2025-05-01 09:00:00','traceroute 등으로 경로를 점검하고 손실 구간을 확인한 뒤, 손실률이 높으면 인프라팀에 보고합니다.'),
  ('hyewon@company.com','차량 주차 등록은 어떻게 하나요?',TIMESTAMP '2025-07-27 09:36:12','buyeon@company.com',TIMESTAMP '2025-07-28 09:00:00','주차 등록은 총무팀에 차량 번호를 등록하면 되며, 지정 주차 구역과 방문객 주차 안내는 사내 포털 공지를 참고하세요.'),
  ('hyewon@company.com','사내망 접속용 기기는 어떻게 등록하나요?',TIMESTAMP '2025-10-22 10:49:13','buyeon@company.com',TIMESTAMP '2025-10-23 09:00:00','사내망 접속용 기기는 MAC 주소를 인프라팀에 등록하면 인증 후 접속할 수 있습니다.'),
  ('hyewon@company.com','스위치/게이트웨이 문제는 누구에게 문의하나요?',TIMESTAMP '2026-04-15 12:15:15','buyeon@company.com',TIMESTAMP '2026-04-16 09:00:00','네트워크 장비 관련 문제는 인프라팀에 문의하며, 사용자가 직접 설정을 변경하지 않습니다.'),
  ('haeun@company.com','사외에서 사내 시스템에 접근하려면 어떻게 하나요?',TIMESTAMP '2025-05-25 13:28:16','buyeon@company.com',TIMESTAMP '2025-05-26 09:00:00','사외 접근은 VPN을 통해서만 허용되며, 접근 권한은 보안·인프라팀 승인을 받아야 합니다.'),
  ('haeun@company.com','점심 식대는 어떻게 지원되나요?',TIMESTAMP '2025-08-16 14:41:17','buyeon@company.com',TIMESTAMP '2025-08-17 09:00:00','점심 식대는 1일 1만원 한도로 법인카드 또는 식대 포인트로 지원되며, 사용 내역은 매월 정산됩니다.'),
  ('haeun@company.com','대역폭이 부족할 때는 어떻게 하나요?',TIMESTAMP '2025-11-06 15:54:18','buyeon@company.com',TIMESTAMP '2025-11-07 09:00:00','대량 다운로드·스트리밍을 줄이고, 지속적으로 부족하면 인프라팀에 회선 증설을 검토 요청합니다.'),
  ('haeun@company.com','사내 IP 대역은 어디서 확인하나요?',TIMESTAMP '2026-04-20 09:20:20','buyeon@company.com',TIMESTAMP '2026-04-21 09:00:00','IP 대역 정보는 인프라팀 문서에서 확인할 수 있으며, 필요 시 접근 권한을 요청하세요.'),
  ('jiho@company.com','새 좌석의 유선 네트워크는 어떻게 신청하나요?',TIMESTAMP '2025-06-19 10:33:21','buyeon@company.com',TIMESTAMP '2025-06-20 09:00:00','좌석 이동이나 신규 배선은 총무팀·인프라팀에 신청하면 배선 및 포트 활성화가 진행됩니다.'),
  ('jiho@company.com','VPN 계정이 잠겼을 때는 어떻게 해제하나요?',TIMESTAMP '2025-11-21 12:59:23','buyeon@company.com',TIMESTAMP '2025-11-22 09:00:00','VPN 계정 잠금은 본인 확인 후 인프라팀 또는 보안 포털을 통해 해제할 수 있습니다.'),
  ('jiho@company.com','재택 중 VPN이 자꾸 끊기면 어떻게 하나요?',TIMESTAMP '2026-04-25 14:25:25','buyeon@company.com',TIMESTAMP '2026-04-26 09:00:00','VPN 클라이언트를 최신 버전으로 재설치하고, 절전 시 네트워크 어댑터 비활성화 옵션을 해제하세요. 계속되면 인프라팀에 문의합니다.'),
  ('yoonseo@company.com','사내망에는 어떻게 접속하나요?',TIMESTAMP '2025-10-10 15:38:26','buyeon@company.com',TIMESTAMP '2025-10-11 09:00:00','사내망은 사무실 유선/사내 WiFi 또는 VPN을 통해 접속하며, 접속 정보는 총무팀·인프라팀 안내를 따릅니다.'),
  ('yoonseo@company.com','명함은 어떻게 신청하나요?',TIMESTAMP '2025-12-18 16:51:27','buyeon@company.com',TIMESTAMP '2025-12-19 09:00:00','명함은 입사 후 총무팀에 신청하며, 직급·부서 정보 확인 후 제작되어 약 3~5영업일 내 수령할 수 있습니다.'),
  ('hyunji@company.com','특정 포트를 열어야 할 때는 어떻게 요청하나요?',TIMESTAMP '2025-09-13 11:30:30','buyeon@company.com',TIMESTAMP '2025-09-14 09:00:00','포트 오픈은 용도·대상·기간을 명시해 인프라팀에 요청하며, 보안 검토를 거쳐 허용됩니다.'),
  ('hyunji@company.com','프록시 설정은 어떻게 하나요?',TIMESTAMP '2025-11-12 12:43:31','buyeon@company.com',TIMESTAMP '2025-11-13 09:00:00','사내 프록시 설정 값은 인프라팀 안내에 따라 적용하며, 일부 도구는 별도 예외 설정이 필요할 수 있습니다.'),
  ('hyunji@company.com','사내 동호회는 어떻게 가입하나요?',TIMESTAMP '2026-01-12 13:56:32','buyeon@company.com',TIMESTAMP '2026-01-13 09:00:00','사내 동호회는 사내 포털 동호회 게시판에서 확인 후 담당자에게 신청하면 되며, 일부 활동비가 지원됩니다.'),
  ('geonwoo@company.com','화상회의 품질이 나쁠 때는 어떻게 개선하나요?',TIMESTAMP '2025-10-25 16:35:35','buyeon@company.com',TIMESTAMP '2025-10-26 09:00:00','유선 연결과 불필요한 대역폭 사용 종료로 개선할 수 있으며, 지속되면 인프라팀에 회선 점검을 요청합니다.'),
  ('geonwoo@company.com','법인카드는 어떤 경우에 사용할 수 있나요?',TIMESTAMP '2026-03-04 10:01:37','buyeon@company.com',TIMESTAMP '2026-03-05 09:00:00','법인카드는 업무 관련 지출(식대·비품·출장 등)에 한해 사용하며, 사용 후 영수증을 첨부해 전자결재로 사용 내역을 보고해야 합니다.'),
  ('harin@company.com','원격 데스크톱 접속은 어떻게 설정하나요?',TIMESTAMP '2025-11-10 12:27:39','buyeon@company.com',TIMESTAMP '2025-11-11 09:00:00','원격 데스크톱은 VPN 접속 후 승인된 계정으로만 가능하며, 설정은 인프라팀 안내를 따릅니다.'),
  ('harin@company.com','VLAN 구성은 누가 관리하나요?',TIMESTAMP '2026-01-10 13:40:40','buyeon@company.com',TIMESTAMP '2026-01-11 09:00:00','VLAN 등 네트워크 구성은 인프라팀이 관리하며, 변경이 필요하면 요청서를 통해 검토·적용합니다.'),
  ('harin@company.com','휴직은 어떻게 신청하나요?',TIMESTAMP '2026-05-12 15:06:42','buyeon@company.com',TIMESTAMP '2026-05-13 09:00:00','휴직은 육아·질병·개인 사유 등이 있으며, 인사팀 상담 후 필요한 증빙과 함께 전자결재로 신청합니다. 종류별 기간과 조건이 다릅니다.'),
  ('yeeun@company.com','인터넷 회선 장애 시 대체 수단이 있나요?',TIMESTAMP '2026-03-19 10:45:45','buyeon@company.com',TIMESTAMP '2026-03-20 09:00:00','회선 장애 시 안내에 따라 대체 회선이나 모바일 테더링을 임시로 사용할 수 있으며, 복구 상황은 인프라팀이 공지합니다.'),
  ('seunghyun@company.com','근태를 잘못 기록했을 때 어떻게 정정하나요?',TIMESTAMP '2026-02-02 12:11:47','buyeon@company.com',TIMESTAMP '2026-02-03 09:00:00','근태 오류는 근태 시스템에서 정정 요청을 상신하고 팀장 승인을 받으면 수정되며, 사유를 명확히 기재해야 합니다.'),
  ('seunghyun@company.com','네트워크 지연이 특정 시간대에만 발생해요.',TIMESTAMP '2026-06-02 15:50:50','buyeon@company.com',TIMESTAMP '2026-06-03 09:00:00','특정 시간대 지연은 트래픽 집중이 원인일 수 있으며, 발생 패턴을 기록해 인프라팀에 전달하면 원인 분석에 도움이 됩니다.'),
  ('sihyeon@company.com','지식문서에 없는 내용은 어디에 질문하면 되나요?',TIMESTAMP '2026-03-21 09:16:52','buyeon@company.com',TIMESTAMP '2026-03-22 09:00:00','먼저 문서 검색을 통해 관련 자료가 있는지 확인한 뒤, 원하는 내용을 찾지 못한 경우 QNA에 질문을 등록하면 됩니다. 반복되는 질문은 관리자가 FAQ 문서로 전환할 수 있습니다.'),
  ('subin@company.com','사내 VPN은 어디서 받아 설치하나요?',TIMESTAMP '2026-03-02 12:55:55','buyeon@company.com',TIMESTAMP '2026-03-03 09:00:00','VPN 클라이언트는 사내 포털 다운로드 센터에서 받을 수 있으며, 설치 후 사번 계정으로 로그인합니다.'),
  ('subin@company.com','신입사원 온보딩 첫 주에는 무엇을 하나요?',TIMESTAMP '2026-05-29 14:21:57','buyeon@company.com',TIMESTAMP '2026-05-30 09:00:00','첫 주는 사원증·장비 수령, 팀장 면담, 부서 OJT, 업무 배정 순으로 진행되며, 상세 일정은 온보딩 문서를 참고하세요.'),
  ('seongmin@company.com','사내망에서 외부 API 호출이 막혀 있어요.',TIMESTAMP '2026-05-31 09:00:00','buyeon@company.com',TIMESTAMP '2026-06-01 09:00:00','방화벽 정책 때문일 수 있으며, 대상 주소와 포트를 정리해 인프라팀에 방화벽 허용을 요청하면 검토 후 오픈됩니다.'),
  ('yejin@company.com','사내 공지는 어디서 확인하나요?',TIMESTAMP '2026-04-26 11:26:02','buyeon@company.com',TIMESTAMP '2026-04-27 09:00:00','사내 공지는 대시보드 공지사항과 Slack #전체공지 채널에서 확인할 수 있으며, 긴급 공지는 별도 알림으로 전달됩니다.'),
  ('hsoyoon@company.com','네트워크가 느릴 때는 어떻게 확인하나요?',TIMESTAMP '2026-05-02 14:05:05','buyeon@company.com',TIMESTAMP '2026-05-03 09:00:00','속도 테스트로 상태를 확인하고 유선 연결을 시도해 보며, 광범위한 지연은 인프라팀에 로그와 함께 신고합니다.'),
  ('yang.gyumin@company.com','급여명세서는 어디서 확인하나요?',TIMESTAMP '2026-05-05 16:31:07','buyeon@company.com',TIMESTAMP '2026-05-06 09:00:00','급여명세서는 ERP 급여 메뉴에서 매월 확인할 수 있으며, 공제 내역에 대한 문의는 인사팀에 하면 됩니다.'),
  ('cyejun@company.com','원격 데스크톱 접속은 어떻게 설정하나요?',TIMESTAMP '2026-05-17 11:10:10','buyeon@company.com',TIMESTAMP '2026-05-18 09:00:00','원격 데스크톱은 VPN 접속 후 승인된 계정으로만 가능하며, 설정은 인프라팀 안내를 따릅니다.'),
  ('yhyewon@company.com','워크숍 참석은 필수인가요?',TIMESTAMP '2026-05-22 13:36:12','buyeon@company.com',TIMESTAMP '2026-05-23 09:00:00','부서 워크숍은 팀 일정에 따라 진행되며, 참석 여부와 일정은 팀장 공지에 따릅니다. 불참이 필요하면 사전에 팀장과 협의하세요.'),
  ('yang.yoonseo@company.com','대역폭이 부족할 때는 어떻게 하나요?',TIMESTAMP '2026-06-10 13:20:20','buyeon@company.com',TIMESTAMP '2026-06-11 09:00:00','대량 다운로드·스트리밍을 줄이고, 지속적으로 부족하면 인프라팀에 회선 증설을 검토 요청합니다.')
) AS a(writer_email,q_title,q_cts,admin_email,ans_date,content)
JOIN users w ON w.email = a.writer_email
JOIN questions q ON q.user_id = w.id AND q.title = a.q_title AND q.created_at = a.q_cts
JOIN users adm ON adm.email = a.admin_email;

